-- V4: transfer module (documentations/01 §7.2, §7.4; doc 06 MVP-ADR-03, -06, -18, -20, -22, -24;
-- doc 07 §1.1, §6, §7). Customer and wallet ids are logical references (no cross-schema FK).

CREATE TABLE transfer.transfers (
  -- Generated by the application before the risk assessment and stored on both rows (doc 08 Q8).
  id                        uuid          NOT NULL DEFAULT gen_random_uuid(),
  reference                 varchar(40)   NOT NULL,
  sender_customer_id        uuid          NOT NULL,
  receiver_customer_id      uuid          NOT NULL,
  sender_wallet_id          uuid          NOT NULL,
  receiver_wallet_id        uuid          NOT NULL,
  amount                    numeric(19,2) NOT NULL,
  currency                  char(3)       NOT NULL,
  -- Customer note, at most 140 characters; never logged (doc 08 Q4).
  description               varchar(140),
  status                    varchar(20)   NOT NULL,
  idempotency_key           uuid          NOT NULL,
  -- Asia/Bangkok submission day; capture and release always use it (MVP-ADR-18, -22).
  limit_date                date          NOT NULL,
  -- Every transfer is assessed before it is stored (MVP-ADR-24); logical reference into risk.
  risk_assessment_id        uuid          NOT NULL,
  held_at                   timestamptz,
  review_expires_at         timestamptz,
  decided_at                timestamptz,
  -- Generic category shown to the customer, never rule details (MVP-ADR-24).
  rejection_reason_category varchar(40),
  -- POSTED exactly when COMPLETED: posting is atomic with the status change (MVP-ADR-03).
  ledger_status             varchar(20),
  correlation_id            varchar(64),
  version                   bigint        NOT NULL DEFAULT 0,
  created_at                timestamptz   NOT NULL DEFAULT now(),
  updated_at                timestamptz   NOT NULL DEFAULT now(),
  CONSTRAINT pk_transfers PRIMARY KEY (id),
  CONSTRAINT uq_transfers_reference UNIQUE (reference),
  -- Keys are scoped per sender, so another customer's key never collides (doc 07 §7).
  CONSTRAINT uq_transfers_sender_idempotency_key UNIQUE (sender_customer_id, idempotency_key),
  CONSTRAINT ck_transfers_not_self_customer CHECK (sender_customer_id <> receiver_customer_id),
  CONSTRAINT ck_transfers_not_self_wallet CHECK (sender_wallet_id <> receiver_wallet_id),
  CONSTRAINT ck_transfers_amount CHECK (amount > 0),
  CONSTRAINT ck_transfers_currency CHECK (currency = 'THB'),
  CONSTRAINT ck_transfers_status CHECK (status IN
    ('COMPLETED', 'PENDING_REVIEW', 'REJECTED', 'CANCELLED', 'EXPIRED', 'BLOCKED')),
  CONSTRAINT ck_transfers_ledger_status CHECK (ledger_status = 'POSTED'),
  CONSTRAINT ck_transfers_completed_posted
    CHECK ((status = 'COMPLETED') = (ledger_status IS NOT NULL)),
  CONSTRAINT ck_transfers_pending_review_hold
    CHECK (status <> 'PENDING_REVIEW' OR (held_at IS NOT NULL AND review_expires_at IS NOT NULL)),
  CONSTRAINT ck_transfers_review_window
    CHECK (review_expires_at IS NULL OR (held_at IS NOT NULL AND review_expires_at > held_at)),
  -- A held transfer has no decision yet.
  CONSTRAINT ck_transfers_pending_review_undecided
    CHECK (status <> 'PENDING_REVIEW'
           OR (decided_at IS NULL AND rejection_reason_category IS NULL)),
  -- These states are only reached by leaving review, which records the decision time. COMPLETED and
  -- BLOCKED are not listed: a transfer created in either state was never decided.
  CONSTRAINT ck_transfers_left_review_decided
    CHECK (status NOT IN ('REJECTED', 'CANCELLED', 'EXPIRED') OR decided_at IS NOT NULL),
  -- Only a rejection carries a category; a risk BLOCK does not (domain Transfer.blocked).
  CONSTRAINT ck_transfers_rejected_category
    CHECK ((status = 'REJECTED') = (rejection_reason_category IS NOT NULL))
);

CREATE INDEX ix_transfers_sender_created ON transfer.transfers (sender_customer_id, created_at);
CREATE INDEX ix_transfers_receiver_created ON transfer.transfers (receiver_customer_id, created_at);
-- New-recipient rule: has the sender completed a transfer to this receiver before (MVP-ADR-24)?
CREATE INDEX ix_transfers_completed_sender_receiver
  ON transfer.transfers (sender_customer_id, receiver_customer_id)
  WHERE status = 'COMPLETED';
-- Expiry job: held transfers by deadline (MVP-ADR-24).
CREATE INDEX ix_transfers_review_expires
  ON transfer.transfers (review_expires_at)
  WHERE status = 'PENDING_REVIEW';

-- The database sets the timestamps, so history cannot be backdated and an already overdue hold
-- cannot be inserted: ck_transfers_review_window compares the application's review_expires_at
-- (from configuration) with this held_at. Only a held transfer has a hold time, and nothing is
-- decided at insert: completed and blocked rows carry neither (domain Transfer.completed, blocked),
-- and ck_transfers_left_review_decided therefore refuses a row inserted as already decided.
CREATE FUNCTION transfer.stamp_transfer_insert() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
  NEW.created_at := now();
  NEW.updated_at := now();
  NEW.held_at := CASE WHEN NEW.status = 'PENDING_REVIEW' THEN now() END;
  NEW.decided_at := NULL;
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_transfers_insert_stamp
  BEFORE INSERT ON transfer.transfers
  FOR EACH ROW EXECUTE FUNCTION transfer.stamp_transfer_insert();

-- Completed transactions cannot be modified (doc 05 §4). Only a transfer in PENDING_REVIEW may
-- change, only to COMPLETED, REJECTED, CANCELLED or EXPIRED (MVP-ADR-24), and only in its
-- decision columns. Every other state is final. Transfers are never deleted.
-- The review deadline decides the direction, with the same boundary as the domain Transfer
-- (expired at exactly review_expires_at): approve, reject and cancel only before it, expire only
-- at or after it. Both compare statement_timestamp(), so time splits at exactly one point: a
-- transaction that began before the deadline but waited on locks cannot decide after it, and can
-- expire the transfer in that same transaction (MVP-ADR-24). decided_at is set by the database when
-- the transfer leaves PENDING_REVIEW. statement_timestamp() is the start of the UPDATE itself, so
-- the row lock must be taken by an earlier statement (the money-movement lock order does).
CREATE FUNCTION transfer.guard_transfer_update() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, pg_temp
AS $$
BEGIN
  IF OLD.status <> 'PENDING_REVIEW' THEN
    RAISE EXCEPTION 'transfer % is % and can no longer change', OLD.id, OLD.status
      USING ERRCODE = 'restrict_violation';
  END IF;

  IF NEW.status NOT IN ('PENDING_REVIEW', 'COMPLETED', 'REJECTED', 'CANCELLED', 'EXPIRED') THEN
    RAISE EXCEPTION 'transfer % cannot move from PENDING_REVIEW to %', OLD.id, NEW.status
      USING ERRCODE = 'restrict_violation';
  END IF;

  IF NEW.status IN ('COMPLETED', 'REJECTED', 'CANCELLED')
     AND statement_timestamp() >= OLD.review_expires_at THEN
    RAISE EXCEPTION 'transfer % review has expired; it cannot move to %', OLD.id, NEW.status
      USING ERRCODE = 'restrict_violation';
  END IF;

  IF NEW.status = 'EXPIRED' AND statement_timestamp() < OLD.review_expires_at THEN
    RAISE EXCEPTION 'transfer % review has not expired yet', OLD.id
      USING ERRCODE = 'restrict_violation';
  END IF;

  IF (NEW.id, NEW.reference, NEW.sender_customer_id, NEW.receiver_customer_id,
      NEW.sender_wallet_id, NEW.receiver_wallet_id, NEW.amount, NEW.currency, NEW.description,
      NEW.idempotency_key, NEW.limit_date, NEW.risk_assessment_id, NEW.held_at,
      NEW.review_expires_at, NEW.correlation_id, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.reference, OLD.sender_customer_id, OLD.receiver_customer_id,
      OLD.sender_wallet_id, OLD.receiver_wallet_id, OLD.amount, OLD.currency, OLD.description,
      OLD.idempotency_key, OLD.limit_date, OLD.risk_assessment_id, OLD.held_at,
      OLD.review_expires_at, OLD.correlation_id, OLD.created_at) THEN
    RAISE EXCEPTION 'transfer % may only change its status and decision fields', OLD.id
      USING ERRCODE = 'restrict_violation';
  END IF;

  IF NEW.status <> 'PENDING_REVIEW' THEN
    NEW.decided_at := statement_timestamp();
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_transfers_update_guard
  BEFORE UPDATE ON transfer.transfers
  FOR EACH ROW EXECUTE FUNCTION transfer.guard_transfer_update();

REVOKE DELETE, TRUNCATE ON transfer.transfers FROM ${app_role};

-- Idempotency for transfers (doc 02 §1.4; doc 06 MVP-ADR-06; doc 07 D02, D03) ----------------
CREATE TABLE transfer.idempotency_records (
  customer_id     uuid        NOT NULL,
  operation       varchar(20) NOT NULL,
  idempotency_key uuid        NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status smallint,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  expires_at      timestamptz NOT NULL,
  CONSTRAINT pk_transfer_idempotency_records PRIMARY KEY (customer_id, operation, idempotency_key),
  CONSTRAINT ck_transfer_idempotency_records_operation CHECK (operation IN ('TRANSFER'))
);

CREATE INDEX ix_transfer_idempotency_records_expires ON transfer.idempotency_records (expires_at);
